{
  "outcome": "proposal",
  "reply": "已按25000元预算、4K PUBG 144Hz目标优先GPU完成选配：Ryzen 7 9800X3D + RTX 4080 SUPER 16GB + B650M MORTAR WIFI + DDR5-6000 CL30 32GB + T500 2TB + 850W金牌ATX3.0电源 + TD500 Mesh V2机箱 + Arctic LF III 360水冷，总价约21680元，兼容性全部通过。目录内RTX 5080/5070 Ti报价均超出剩余预算或性价比不及4080S，故保留4080S作为4K高帧PUBG主力；实际4K 144Hz需依赖中高画质与DLSS/帧生成，极端画质下可能无法全程锁定144fps，建议以实测为准。散热能力字段缺失属资料未录入，不影响已知兼容性与装机可行性。",
  "draft": {
    "schema_version": 1,
    "requirement_ref": "current",
    "build_ref": "proposal",
    "selection": {
      "cpu": "cpu-r7-9800x3d",
      "gpu": "gpu-asus-4080s-tuf",
      "motherboard": "mb-msi-b650m-mortar-wifi",
      "memory": "mem-corsair-veng-32-6000",
      "ssd": [
        {
          "sku": "ssd-crucial-t500-2tb",
          "quantity": 1
        }
      ],
      "psu": "psu-seasonic-focus-gx850-atx30",
      "case": "case-coolermaster-td500-mesh-v2",
      "cooler": "cooler-arctic-lf3-360"
    },
    "rationale": {
      "cpu": "9800X3D为AM5游戏旗舰，PUBG等缓存敏感游戏受益明显",
      "gpu": "RTX 4080 SUPER 16GB在4K PUBG高帧率下性能充足，优先GPU预算；目录内RTX 5080/5070Ti报价超预算或无更优性价比",
      "motherboard": "B650M MORTAR WIFI支持AM5/DDR5，供电与扩展满足9800X3D",
      "memory": "DDR5-6000 CL30 32GB兼顾容量与延迟，适配AM5甜点频率",
      "ssd": "T500 2TB PCIe4.0 NVMe，加载与系统响应快",
      "psu": "850W金牌ATX3.0带原生16pin，满足4080S峰值功耗",
      "case": "TD500 Mesh V2兼容ATX/MATX、显卡长度与360冷排",
      "cooler": "Liquid Freezer III 360压制9800X3D满载温度"
    }
  },
  "assessments": [
    {
      "field": "budget_cny",
      "status": "met",
      "explanation": "总价21680.08元，低于25000元必须预算上限",
      "evidence": [
        "local:cpu-r7-9800x3d",
        "local:gpu-asus-4080s-tuf",
        "local:mb-msi-b650m-mortar-wifi",
        "local:mem-corsair-veng-32-6000",
        "local:ssd-crucial-t500-2tb",
        "local:psu-seasonic-focus-gx850-atx30",
        "local:case-coolermaster-td500-mesh-v2",
        "local:cooler-arctic-lf3-360"
      ]
    },
    {
      "field": "priority",
      "status": "met",
      "explanation": "GPU占总价约41%，为当前预算内最强可选4K游戏卡；目录内更高阶GPU（5080/5070Ti）报价导致整机超预算或挤压其他必要配件",
      "evidence": [
        "local:gpu-asus-4080s-tuf",
        "local:gpu-gb-5080-gaming",
        "local:gpu-msi-5070ti-ventus3x"
      ]
    },
    {
      "field": "use_case.type",
      "status": "met",
      "explanation": "全平台面向游戏用途选型，CPU/GPU/内存/SSD均为游戏向配置",
      "evidence": [
        "local:cpu-r7-9800x3d",
        "local:gpu-asus-4080s-tuf"
      ]
    },
    {
      "field": "use_case.titles",
      "status": "met",
      "explanation": "9800X3D大缓存+4080S 16GB显存组合适合PUBG 4K高帧；实际帧率受画质/DLSS设置影响，未承诺稳定144fps",
      "evidence": [
        "local:cpu-r7-9800x3d",
        "local:gpu-asus-4080s-tuf"
      ]
    },
    {
      "field": "use_case.resolution",
      "status": "met",
      "explanation": "4080S具备4K输出能力与足够显存，配合DLSS/帧生成可在PUBG实现高帧率；极端画质下可能需调整设置以接近144Hz目标",
      "evidence": [
        "local:gpu-asus-4080s-tuf"
      ]
    },
    {
      "field": "use_case.fps_target",
      "status": "unknown",
      "explanation": "无4K PUBG 144Hz实测数据保证；选型方向合理但实际帧率取决于画质、DLSS版本及系统调校，需用户实测验证",
      "evidence": []
    }
  ],
  "issues": [],
  "assumptions": [
    "用户接受4K PUBG 144Hz需配合DLSS/帧生成及中高画质设置，非全极致画质锁帧",
    "散热能力字段缺失不影响已知物理兼容与装机可行性，实际温控以安装后测试为准",
    "未指定外观/静音/品牌偏好，按性能与预算最优原则选配"
  ]
}
